command:
set -euo pipefail; ADB=adb; SERIAL=$($ADB devices | awk 'NR>1 && $2=="device" {print $1; exit}'); test -n "$SERIAL"; test "$($ADB -s "$SERIAL" shell getprop ro.product.model | tr -d '\r')" = 'SM-S906B'; $ADB -s "$SERIAL" shell input keyevent 224 >/dev/null 2>&1 || true; $ADB -s "$SERIAL" shell wm dismiss-keyguard >/dev/null 2>&1 || true; $ADB -s "$SERIAL" shell monkey -p io.blueeye -c android.intent.category.LAUNCHER 1 >/dev/null; sleep 3; OUT="$HOME/agent-workspace/repos/tracker/checkpoints/ui-p1-real-radar-v3"; mkdir -p "$OUT"; $ADB -s "$SERIAL" shell uiautomator dump /sdcard/p1-v3-initial.xml >/dev/null; $ADB -s "$SERIAL" pull /sdcard/p1-v3-initial.xml "$OUT/initial.xml" >/dev/null; if grep -q 'text="Paused"' "$OUT/initial.xml"; then python3 -c "import re,subprocess,pathlib; s=pathlib.Path('$OUT/initial.xml').read_text(); m=re.search(r'content-desc=\"Scan\"[^>]*bounds=\"\[([0-9]+),([0-9]+)\]\[([0-9]+),([0-9]+)\]\"',s); assert m,'Scan button not found'; x=(int(m.group(1))+int(m.group(3)))//2; y=(int(m.group(2))+int(m.group(4)))//2; subprocess.check_call(['adb','-s','$SERIAL','shell','input','tap',str(x),str(y)])"; echo P1_SCAN_STARTED_FROM_PAUSED; fi; sleep 20; $ADB -s "$SERIAL" shell uiautomator dump /sdcard/p1-v3-a.xml >/dev/null; $ADB -s "$SERIAL" pull /sdcard/p1-v3-a.xml "$OUT/a.xml" >/dev/null; sleep 5; $ADB -s "$SERIAL" shell uiautomator dump /sdcard/p1-v3-b.xml >/dev/null; $ADB -s "$SERIAL" pull /sdcard/p1-v3-b.xml "$OUT/b.xml" >/dev/null; python3 -c "import re,pathlib; out=pathlib.Path('$OUT');
for n in ('a','b'):
 s=(out/f'{n}.xml').read_text(); seen=re.findall(r'text=\"Seen ([^\"]+) • ([^\"]+)\"[^>]*bounds=\"\[([0-9]+),([0-9]+)\]\[([0-9]+),([0-9]+)\]\"',s); rssi=re.findall(r'text=\"(-?[0-9]+ dBm)\"',s); print('P1_'+n.upper()+'_SEEN_ROWS',len(seen),'RSSI_LABELS',len(rssi),'SEEN_SAMPLE',[x[0]+' '+x[1] for x in seen[:5]]); ys=[(int(x[3])+int(x[5]))//2 for x in seen]; gaps=[b-a for a,b in zip(ys,ys[1:]) if b>a]; print('P1_'+n.upper()+'_ROW_GAPS',gaps[:10]);
assert len(re.findall(r'text=\"Seen ',(out/'a.xml').read_text()))>0,'No live Radar cards after scan wait'"; echo P1_REAL_RADAR_VISIBLE_PASS
